#!/usr/bin/env bash
if ! command -v python3 >/dev/null 2>&1; then echo 'python3 diperlukan untuk decoder Custom Encrypt' >&2; exit 127; fi
NulvexRun=$(cat <<'NulvexDATA' | python3 -c 'import sys
data=sys.stdin.read()
bits=[]
for ch in data:
    if ch == '\''\u200c'\'': bits.append('\''0'\'')
    elif ch == '\''\u200d'\'': bits.append('\''1'\'')
out=bytearray()
for i in range(0,len(bits),8):
    out.append(int('\'''\''.join(bits[i:i+8]),2))
chk=0
for b in out:
    chk=((chk*131)+b)&0xffffffff
if len(out)!=21747 or chk!=592454456:
    raise SystemExit('\''Payload rusak'\'')
sys.stdout.write(out.decode('\''utf-8'\''))'
